@@ -0,0 +1,40 @@
+import { describe, expect, it } from 'vitest';
+import { validateTime } from '../validateTime';
+
+export const validTimes = [
+  ['Midnight', '00:00'],
+  ['Last minute of the day', '23:59'],
+  ['Default daily time', '09:52'],
+  ['Night time', '04:30'],
+  ['Noon', '12:00'],
+  ['Start of the 20s', '20:00'],
+];
+
+export const invalidTimes = [
+  ['Empty string', ''],
+  ['Hour out of range', '24:00'],
+  ['Minute out of range', '12:60'],
+  ['Single digit hour', '9:15'],
+  ['Single digit minute', '09:5'],
+  ['No colon', '0930'],
+  ['Seconds', '09:15:30'],
+  ['Dot separator', '09.15'],
+  ['Letters', 'ab:cd'],
+  ['Leading space', ' 09:15'],
+  ['12-hour suffix', '09:15 PM'],
+  ['Negative', '-1:00'],
+];
+
+describe('validateTime', () => {
+  describe.each(validTimes)('Valid time: %s', (_desc, time) => {
+    it(`returns valid=true for "${time}"`, () => {
+      expect(validateTime(time).valid).toBe(true);
+    });
+  });
+
+  describe.each(invalidTimes)('Invalid time: %s', (_desc, time) => {
+    it(`returns valid=false for "${time}"`, () => {
+      expect(validateTime(time).valid).toBe(false);
+    });
+  });
+});
diff --git a/fe-app-netshift/src/validators/validateTime.ts b/fe-app-netshift/src/validators/validateTime.ts
new file mode 100644
index 0000000..802f77f
--- /dev/null
+++ b/fe-app-netshift/src/validators/validateTime.ts
@@ -0,0 +1,23 @@
+import { ValidationResult } from './types';
+
+// Time of day as HH:MM, 00:00-23:59 (two digits each, 24-hour clock).
+export function validateTime(value: string): ValidationResult {
+  if (!value) {
+    return {
+      valid: false,
+      message: _('Time cannot be empty'),
+    };
+  }
+
+  if (/^([01][0-9]|2[0-3]):[0-5][0-9]$/.test(value)) {
+    return {
+      valid: true,
+      message: _('Valid'),
+    };
+  }
+
+  return {
+    valid: false,
+    message: _('Invalid time format. Use HH:MM from 00:00 to 23:59'),
+  };
+}
